// מה רצוי: F-39 AC2 «כשל במסירה מוצג למשתמש בעברית ולא נבלע בשקט»; F-88 AC4 / S-02 — остаёмся на экране и можем повторить.
// + #02f519 (4a56edffc3e70c195302f519, ticket 25) «Android — офлайн-отправка кода говорит об ошибке сервера» — наш баг 03.11,
// עבר QA пользователем 03.11.2026 («прошли»). Источник: S-02 AC1 — без сети сообщение называет причину (связь), а не сервер.
// Факт 03.11 14:26 (до фикса, otp-0311-android-11): «הקוד לא נשלח: השרת החזיר שגיאה שאיננו יודעים לפרט. נסו שוב בעוד רגע.»
// Факт 03.11 16:18 (после фикса, Pixel 6, app 1.0.0 (6) + OTA, 2× перезапуск онлайн; 02f519-0311b-android-01-offline.png):
// авиарежим → «שילחו קוד אימות» → «הקוד לא נשלח: אין תשובה מהשרת. בדקו את חיבור האינטרנט ונסו שוב.»; кнопка остаётся активной,
// повторное нажатие — то же сообщение. Проверяем: префикс «הקוד לא נשלח» + иврит, содержит «בדקו את חיבור האינטרנט»,
// НЕ содержит «השרת החזיר שגיאה»; экран номера остаётся, экрана кода нет; повтор → то же сообщение, кнопка активна.
//
// Полностью автоматический, SMS не отправляется (сети нет). Сеть: `mobile: setConnectivity` (Wi‑Fi + данные); если Appium/телефон
// не дают (данные без root) или QA_OFFLINE_MANUAL=1 — сеть выключает/включает человек (тест ждёт).
// @data: выходит из аккаунта; в конце сеть включается и вход восстанавливается (USER1 через login(); при несовпадении OTP — человек).
// Кейс: .qa/tests/auth-login/AL-08-otp-send-failure-offline.md.
import { driver, expect } from '@wdio/globals';
import { byText } from '../../helpers/ui.ts';
import { ensureAppReady, isLoggedIn } from '../../helpers/app.ts';
import { skipWith } from '../_lib/app-0710.ts';
import {
  toPhoneScreen, submitPhone, expectHebrewMessage, messageStartingWith, setOnline, OTP_PHONE, PHONE_TITLE, SEND_CODE, NOT_SENT_PREFIX,
  OFFLINE_HINT, SERVER_ERROR_TEXT, CODE_TITLE, MANUAL_WAIT,
} from '../_lib/app-0311.ts';

const PHONE = OTP_PHONE || process.env.QA_USER1_PHONE || '';

describe('03.11 — сбой отправки кода без сети: сообщение на иврите о связи (#41747e, #02f519)', function () {
  let wentOffline = false;
  before(async function () {
    if (!driver.isAndroid) skipWith(this, 'OTP-пакет 03.11 принят на Android (Pixel 6)');
    if (!PHONE) skipWith(this, 'нет QA_OTP_PHONE / QA_USER1_PHONE');
  });
  after(async function () {
    this.timeout(2 * MANUAL_WAIT + 60000);
    if (wentOffline) await setOnline(true);
    if (!(await isLoggedIn())) {
      await ensureAppReady().catch((e) => console.log(`[Q-23] вход USER1 не восстановлен (${(e as Error).message}) — войти вручную`));
    }
  });

  it('Q-23 Без сети: номер → «שילחו קוד אימות» → «הקוד לא נשלח: … בדקו את חיבור האינטרנט …» на иврите, без «השרת החזיר שגיאה»; остаёмся на «כניסה דרך מספר נייד», экрана кода нет, кнопка активна, повтор → то же #41747e #02f519 @android @data', async function () {
    this.timeout(MANUAL_WAIT + 180000);
    await toPhoneScreen();                 // выход — пока сеть есть
    await setOnline(false);
    wentOffline = true;

    // 1-е нажатие.
    await submitPhone(PHONE);
    const msg = await expectHebrewMessage(NOT_SENT_PREFIX, 45000);
    console.log(`[Q-23] 1: «${msg}»`);
    expect(msg.startsWith(NOT_SENT_PREFIX)).toBe(true);
    expect(msg).toContain(OFFLINE_HINT);                  // #02f519: причина — интернет
    expect(msg).not.toContain(SERVER_ERROR_TEXT);         // #02f519: не «сервер вернул ошибку»
    await expect(byText(PHONE_TITLE)).toBeDisplayed();
    await expect(byText(CODE_TITLE)).not.toBeExisting();
    const send = await byText(SEND_CODE);
    await expect(send).toBeDisplayed();
    expect(await send.isEnabled()).toBe(true);

    // 2-е нажатие (сеть всё ещё выключена) — то же сообщение, экран тот же, кнопка снова активна.
    await send.click();
    await expect(byText(CODE_TITLE)).not.toBeExisting();
    const msg2 = await expectHebrewMessage(NOT_SENT_PREFIX, 45000);
    console.log(`[Q-23] 2: «${msg2}»`);
    expect(msg2).toContain(OFFLINE_HINT);
    expect(msg2).not.toContain(SERVER_ERROR_TEXT);
    expect(msg2).toBe(msg);
    expect(await messageStartingWith(NOT_SENT_PREFIX)).toBe(msg);
    await expect(byText(PHONE_TITLE)).toBeDisplayed();
    expect(await (await byText(SEND_CODE)).isEnabled()).toBe(true);
  });
});
